package io.github.polestarcn.companion;
import static org.junit.Assert.*;import android.content.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class EnergyLogTest {
 Context c;EnergyLog log;long now;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();try{java.lang.reflect.Field f=EnergyLog.class.getDeclaredField("instance");f.setAccessible(true);EnergyLog old=(EnergyLog)f.get(null);if(old!=null)old.close();f.set(null,null);}catch(Exception e){throw new AssertionError(e);}c.deleteDatabase("energy_history.db");c.getSharedPreferences("preferences",0).edit().clear().commit();log=EnergyLog.get(c);now=System.currentTimeMillis();}
 VehicleSnapshot s(long t,int soc,double km,double consumption,String climate,String charge){return new VehicleSnapshot("car","masked",soc,200,10000,charge,"全部关闭","全部关闭","已关闭","已上锁",t,"LIVE",false,climate,"关闭").withMileage(new MileageSnapshot((long)(km*1000),km,1.,40.,30.,consumption,18.,t,t));}
 @Test public void stationaryClimateDropsConvertUsingSeventyOneKwhAndDoNotMixVehicles(){log.append("a",s(now-600000,70,100,20,"开启","空闲"));log.append("a",s(now-300000,69,100,20,"开启","空闲"));log.append("a",s(now,68,100,20,"开启","空闲"));EnergyLog.Report r=log.read("a",1);assertEquals(2,r.ac,0);assertEquals(1.42,r.ac*.71,.0001);assertEquals(0,r.drive,0);assertEquals(0,log.read("b",1).count);}
 @Test public void movingAndChargingAndLongGapsDoNotCountAsParkedClimate(){log.append("a",s(now-900000,70,100,20,"开启","空闲"));log.append("a",s(now-600000,69,110,20,"开启","空闲"));log.append("a",s(now,68,110,20,"开启","充电中"));assertEquals(0,log.read("a",1).ac,0);assertEquals(2,log.read("a",1).drive,.001);}
 @Test public void manualResetDoesNotCreateNegativeOrInventedEnergy(){log.append("a",s(now-900000,70,100,20,"关闭","空闲"));log.append("a",s(now-600000,69,110,20,"关闭","空闲"));log.append("a",s(now-300000,69,0,20,"关闭","空闲"));log.append("a",s(now,68,10,20,"关闭","空闲"));assertEquals(4,log.read("a",1).drive,.001);}
 @Test public void duplicateReadbacksAndCachedSnapshotsDoNotGrowDatabase(){VehicleSnapshot v=s(now,70,100,20,"开启","空闲");log.append("a",v);log.append("a",v);log.append("a",s(now-1000,70,100,20,"开启","空闲"));assertEquals(1,log.read("a",1).count);}
 @Test public void retentionClampsToTwoYearsAndClearingRemovesObservations(){AppPreferences.set(c,"energy_months","99");assertEquals(24,EnergyLog.months(c));log.append("a",s(now,70,100,20,"关闭","空闲"));log.clear();assertEquals(0,log.read("a",1).count);}
 @Test public void energyScreenLoadsLocalHistoryWithoutNetworkAndSurvivesClose()throws Exception{String id=String.format(java.util.Locale.ROOT,"%064d",0);log.append(id,s(now-300000,70,100,20,"开启","空闲"));log.append(id,s(now,69,100,20,"开启","空闲"));android.content.Intent intent=new android.content.Intent(c,EnergyActivity.class).putExtra("vehicle",id);org.robolectric.android.controller.ActivityController<EnergyActivity> controller=Robolectric.buildActivity(EnergyActivity.class,intent).setup();EnergyLog.WORK.submit(()->{}).get(10,java.util.concurrent.TimeUnit.SECONDS);org.robolectric.shadows.ShadowLooper.shadowMainLooper().idle();assertFalse(controller.get().isFinishing());android.view.View root=controller.get().getWindow().getDecorView();root.measure(android.view.View.MeasureSpec.makeMeasureSpec(360,android.view.View.MeasureSpec.EXACTLY),android.view.View.MeasureSpec.makeMeasureSpec(780,android.view.View.MeasureSpec.EXACTLY));root.layout(0,0,360,780);assertNotNull(root.findViewById(android.R.id.content));controller.pause().stop().destroy();}

}
